import{_ as t,o as r,c as o,a5 as e}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"YSB0067-批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名(解压后删除压缩包)","日期":"2026-04-11T00:00:00.000Z","修改日期":"2026-04-11T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Bat批处理"],"标签":["压缩包批量解压","压缩包解压","批量解压压缩包","批量解压指定格式压缩包","解压压缩包"]},"headers":[],"relativePath":"md/Bat批处理/YSB0067-批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名(解压后删除压缩包).md","filePath":"md/Bat批处理/YSB0067-批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名(解压后删除压缩包).md"}'),n={name:"md/Bat批处理/YSB0067-批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名(解压后删除压缩包).md"};function p(s,a,_,i,l,h){return r(),o("div",null,[...a[0]||(a[0]=[e('<h2 id="批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名-解压后删除压缩包" tabindex="-1">批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名(解压后删除压缩包) <a class="header-anchor" href="#批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名-解压后删除压缩包" aria-label="Permalink to &quot;批量解压当前文件夹下指定格式压缩包并以压缩包名字命名解压后的文件夹名(解压后删除压缩包)&quot;">​</a></h2><p>winrar程序支持的压缩包格式都可以，几乎支持所有类型压缩文件,</p><p>主要功能是解压指定格式的压缩文件并删除源文件，且解压后的文件会放在一个与压缩包名字一样的文件夹内。</p><p>在运行脚本时，它会要求用户输入压缩文件的格式（例如：rar）输入后回车确认，</p><p>程序自动运行解压文件并创建与压缩包名字一样的文件夹，压缩包解压进去，脚本将不断循环这个过程，</p><p>以便用户可以对其他格式的压缩文件（例如zip，rar）执行相同的操作。</p><h3 id="▶程序截图-可能随更新有些许变化" tabindex="-1"><strong>▶程序截图，可能随更新有些许变化</strong> <a class="header-anchor" href="#▶程序截图-可能随更新有些许变化" aria-label="Permalink to &quot;**▶程序截图，可能随更新有些许变化**&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250221142228174011894848546.png" alt=""></p><h3 id="▶【以下支持】" tabindex="-1"><strong>▶【以下支持】：</strong> <a class="header-anchor" href="#▶【以下支持】" aria-label="Permalink to &quot;**▶【以下支持】：**&quot;">​</a></h3><p>【1】、支持的文件格式：自行指定文件类型</p><p>【2】、是否支持子文件夹穿透：不支持</p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多不同类型的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有文件。</p><p>【操作方法】：将程序放在A文件夹下，运行程序胡，会将A文件夹下指定的压缩包格式比如zip批量分别解压，创建以压缩包名字命名的文件夹，然后将解压后的文件放在创建的文件夹内，解压完成后会删除原压缩包文件。注意：不支持子文件夹下B、C、D....等文件夹的压缩包解压。</p><h3 id="▶-winrar程序安装说明-这步必须操作" tabindex="-1">**▶ **winrar程序安装说明，这步必须操作： <a class="header-anchor" href="#▶-winrar程序安装说明-这步必须操作" aria-label="Permalink to &quot;**▶ **winrar程序安装说明，这步必须操作：&quot;">​</a></h3><p>注意：安装路径必须为此处：D:\\rar\\，**提示：**请提前在D盘创建文件夹：rar</p><p>如果没有D盘，则安装在C盘，然后修改代码部分即可，如下所示：</p><p>将代码中的这部分代码 set &quot;rar=D:\\rar\\WinRAR.exe&quot; 修改为 set &quot;rar=C:\\rar\\WinRAR.exe&quot; 即可</p><h3 id="📑-bat程序下一步执行方法" tabindex="-1">📑 bat程序下一步执行方法 <a class="header-anchor" href="#📑-bat程序下一步执行方法" aria-label="Permalink to &quot;📑 bat程序下一步执行方法&quot;">​</a></h3><p>**▶ **使用时，<strong>键盘回车键（就是键盘上的 ENTER 键）</strong>“回车确认”是执行下一步的方法 ，</p><p>比如将路径复制到程序中后，回车键确认执行下一步，每一步输入后，回车键确认即可向下执行。</p><p><strong>▶ 注意：请先测试备份原文件再批量使用，以免造成不可逆损失！！！</strong></p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250221142406174011904695945.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>：建议win7及以上64位win操作系统，mac系统需要定制。</p><p><strong>注意事项：bat程序原理上是支持</strong>win32位系统的，但不能完全确定。</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：程序不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1356.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1356.html</a></p>',28)])])}const g=t(n,[["render",p]]);export{d as __pageData,g as default};
